import { inferRouterInputs, initTRPC } from '@trpc/server';
import { z } from 'zod';

type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
declare function assertTrue<T extends true>(): void;
declare function show<T>(x: T): { __shown: T };

// A: regression
const t = initTRPC.create();
const r = t.router({
  s: t.procedure.input(z.string()).use((o) => o.next()).query(({ input }) => input),
  obj: t.procedure.input(z.object({ a: z.string() })).use((o) => o.next()).input(z.object({ b: z.number() })).query(({ input }) => input),
  strThenObj: t.procedure.input(z.string()).input(z.object({ b: z.number() })).query(({ input }) => input),
});
type In = inferRouterInputs<typeof r>;
assertTrue<Equal<In['s'], string>>();
assertTrue<Equal<In['obj'], { a: string; b: number }>>();

// B: ctx any
const ta = initTRPC.context<any>().create();
ta.procedure
  .use((o) => o.next({ ctx: { extra: 1 } }))
  .query(({ ctx }) => {
    const e: number = ctx.extra;
    const never_: never = ctx; // prints ctx type
    return e;
  });

// C: ctx union
const tu = initTRPC.context<{ a: 1 } | { b: 2 }>().create();
tu.procedure
  .use((o) => o.next({ ctx: { extra: 1 } }))
  .query(({ ctx }) => {
    const never_: never = ctx; // prints ctx type
    return 1;
  });

// D: plain
const tp = initTRPC.context<{ user: string }>().create();
tp.procedure
  .use((o) => o.next({ ctx: { extra: 1 } }))
  .query(({ ctx }) => {
    const never_: never = ctx;
    return 1;
  });
EOF
